<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Services\AccountingPostingService;use App\Services\BusinessTimeService;use App\Services\DocumentNumberService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class FinanceExpansionController extends Controller{
 public function __construct(private DocumentNumberService $numbers,private BusinessTimeService $businessTime){}
 public function shifts(Request$r){$page=DB::table('cashier_shifts')->when($r->filled('cashier_id'),fn($q)=>$q->where('cashier_id',$r->cashier_id))->when($r->filled('branch_id'),fn($q)=>$q->where('branch_id',$r->branch_id))->when($r->filled('status'),fn($q)=>$q->where('status',$r->status))->orderByDesc('id')->paginate(min(100,max(1,$r->integer('per_page',25))));$page->through(fn($s)=>$this->presentShift($s));return $this->collection($page);}
 public function current(Request$r){$s=DB::table('cashier_shifts')->where(['cashier_id'=>$r->user()->id,'status'=>'open'])->when($r->filled('branch_id'),fn($q)=>$q->where('branch_id',$r->branch_id))->latest('id')->first();return $this->success($s?$this->shiftData($s):null);}
 public function shiftOpen(Request$r){$v=$r->validate(['branch_id'=>'required|exists:branches,id','opening_cash'=>'required|numeric|min:0']);if(DB::table('cashier_shifts')->where(['cashier_id'=>$r->user()->id,'branch_id'=>$v['branch_id'],'status'=>'open'])->exists())abort(409,'An open shift already exists.');$timestamp=$this->businessTime->utcTimestamp();$id=DB::table('cashier_shifts')->insertGetId(['cashier_id'=>$r->user()->id,'branch_id'=>$v['branch_id'],'status'=>'open','opening_cash'=>$v['opening_cash'],'opened_at'=>$timestamp,'created_at'=>$timestamp,'updated_at'=>$timestamp]);return $this->success($this->shiftData(DB::table('cashier_shifts')->find($id)),201);}
 public function shiftShow(int$id){$s=DB::table('cashier_shifts')->find($id);abort_unless($s,404);return $this->success($this->shiftData($s));}
 public function shiftClose(Request$r,int$id){$v=$r->validate(['counted_cash'=>'required|numeric|min:0','notes'=>'nullable|string']);$s=DB::table('cashier_shifts')->where('id',$id)->lockForUpdate()->first();if(!$s||$s->status!=='open')abort(409,'Shift is not open.');$data=$this->shiftData($s);$timestamp=$this->businessTime->utcTimestamp();DB::table('cashier_shifts')->where('id',$id)->update(['status'=>'closed','expected_cash'=>$data['expected_cash'],'counted_cash'=>$v['counted_cash'],'difference'=>$v['counted_cash']-$data['expected_cash'],'notes'=>$v['notes']??null,'opened_at'=>$s->opened_at,'closed_at'=>$timestamp,'updated_at'=>$timestamp]);return $this->success($this->shiftData(DB::table('cashier_shifts')->find($id)));}
 public function otherIncomeStore(Request$r){$v=$r->validate(['date'=>'required|date','branch_id'=>'nullable|exists:branches,id','account_id'=>'required|exists:accounts,id','amount'=>'required|numeric|gt:0','payment_method'=>'required|in:cash,bank','description'=>'required|string','reference'=>'nullable|string']);abort_unless(DB::table('accounts')->where('id',$v['account_id'])->where('account_type','revenue')->where('active',true)->exists(),422,'Other-income account must be an active revenue account.');$id=DB::transaction(function()use($v,$r){$id=DB::table('other_incomes')->insertGetId(array_merge($v,['document_number'=>$this->numbers->next('other_income','OIN'),'status'=>'posted','posted_at'=>now(),'user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]));app(AccountingPostingService::class)->postOtherIncome($id);app(\App\Services\PrintIdentityService::class)->capture('other_income',$id);return$id;});return $this->success(DB::table('other_incomes')->find($id),201);}
 public function otherIncomes(Request$r){$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from','branch_id'=>'nullable|exists:branches,id','account_id'=>'nullable|exists:accounts,id','payment_method'=>'nullable|in:cash,bank','status'=>'nullable|in:posted,cancelled']);$q=DB::table('other_incomes')->when($r->from,fn($q)=>$q->whereDate('date','>=',$r->from))->when($r->to,fn($q)=>$q->whereDate('date','<=',$r->to))->when($r->branch_id,fn($q)=>$q->where('branch_id',$r->branch_id))->when($r->account_id,fn($q)=>$q->where('account_id',$r->account_id))->when($r->payment_method,fn($q)=>$q->where('payment_method',$r->payment_method))->when($r->status,fn($q)=>$q->where('status',$r->status));return $this->collection($q->orderByDesc('id')->paginate(min(100,max(1,$r->integer('per_page',25)))));}
 public function otherIncomeShow(int$id){$row=DB::table('other_incomes')->find($id);abort_unless($row,404);return $this->success($row);}
 public function otherIncomeCancel(Request$r,int$id){$v=$r->validate(['reason'=>'required|string|max:1000']);$row=DB::transaction(function()use($r,$id,$v){$row=DB::table('other_incomes')->where('id',$id)->lockForUpdate()->first();if(!$row||$row->status!=='posted')abort(409,'Other income is not posted.');app(AccountingPostingService::class)->reverseEvent('other_income',$id,$row->date,$r->user()->id,'Other income cancellation: '.$v['reason']);DB::table('other_incomes')->where('id',$id)->update(['status'=>'cancelled','cancelled_at'=>now(),'cancelled_by'=>$r->user()->id,'cancellation_reason'=>$v['reason'],'updated_at'=>now()]);return DB::table('other_incomes')->find($id);});return $this->success($row);}
 public function arAging(Request$r){return $this->agingResponse(app(\App\Services\AgingService::class)->report($r,'customer'));} public function apAging(Request$r){return $this->agingResponse(app(\App\Services\AgingService::class)->report($r,'supplier'));}
 private function agingResponse(array$x){return response()->json(['success'=>true,'message'=>'Aging report retrieved.','data'=>$x['data'],'meta'=>$x['meta'],'aging'=>['as_of'=>$x['as_of'],'side'=>$x['side']]]);}
 private function shiftData($s):array{$lines=DB::table('cash_movements')->where('responsible_user_id',$s->cashier_id)->where('branch_id',$s->branch_id)->where('occurred_at','>=',$s->opened_at)->when($s->closed_at,fn($q)=>$q->where('occurred_at','<=',$s->closed_at))->orderBy('occurred_at')->get();$in=(float)$lines->where('direction','in')->sum('amount');$out=(float)$lines->where('direction','out')->sum('amount');$legacy=DB::table('journal_entry_lines as l')->join('journal_entries as e','e.id','=','l.journal_entry_id')->join('accounts as a','a.id','=','l.account_id')->leftJoin('cash_movements as cm','cm.journal_entry_line_id','=','l.id')->whereNull('cm.id')->where('a.code','1100')->where('e.status','posted')->where('e.created_at','>=',$s->opened_at)->when($s->closed_at,fn($q)=>$q->where('e.created_at','<=',$s->closed_at))->sum('l.amount');return array_merge($this->presentShift($s),['cash_in'=>$in,'cash_out'=>$out,'expected_cash'=>round((float)$s->opening_cash+$in-$out,2),'attribution_complete'=>(float)$legacy===0.0,'unattributed_cash_amount'=>round((float)$legacy,2),'movements'=>$lines->map(function($line){if(isset($line->occurred_at))$line->occurred_at=$this->businessTime->toBusinessTimestamp((string)$line->occurred_at);return$line;})->values()]);}
 private function presentShift($s):array{$row=(array)$s;$row['cashier_name']=DB::table('users')->where('id',$s->cashier_id)->value('name');foreach(['opened_at','closed_at','created_at','updated_at']as$field)if(!empty($row[$field]))$row[$field]=$this->businessTime->toBusinessTimestamp((string)$row[$field]);return$row;}
 private function aging(Request$r,string$type){$v=$r->validate(['as_of'=>'nullable|date','party_id'=>'nullable|integer','minimum_balance'=>'nullable|numeric|min:0','outstanding_only'=>'nullable|boolean','per_page'=>'nullable|integer|min:1|max:100']);$as=$v['as_of']??now()->toDateString();$table=$type==='customer'?'customers':'providers';$invoice=$type==='customer'?'sales_invoices':'purchase_invoices';$partyCol=$type==='customer'?'customer_id':'provider_id';$amountCol=$type==='customer'?'total_price':'amount';$parties=DB::table($table)->when($v['party_id']??null,fn($q)=>$q->where('id',$v['party_id']))->orderBy('id')->paginate($v['per_page']??25);$parties->through(function($p)use($type,$invoice,$partyCol,$amountCol,$as,$v){$balance=(float)app(\App\Services\AccountingReportService::class)->{$type==='customer'?'customerStatement':'supplierStatement'}($p->id,null,$as)['balance'];$docs=DB::table($invoice)->where($partyCol,$p->id)->whereDate('date','<=',$as)->when($type==='customer',fn($q)=>$q->whereNull('deleted_at'))->orderBy('date')->get(['id','date',$amountCol.' as amount']);$remaining=max(0,$balance);$b=['current'=>0.0,'0_30'=>0.0,'31_60'=>0.0,'61_90'=>0.0,'90_plus'=>0.0];foreach($docs->reverse()as$d){if($remaining<=0)break;$x=min($remaining,(float)$d->amount);$days=now()->parse($d->date)->diffInDays(now()->parse($as));$key=$days===0?'current':($days<=30?'0_30':($days<=60?'31_60':($days<=90?'61_90':'90_plus')));$b[$key]+=$x;$remaining-=$x;}$p->total_outstanding=round(max(0,$balance),2);$p->buckets=$b;$p->aging_basis='Deterministic pooled AR/AP balance allocated newest-document-first because receipts/payments lack invoice allocation.';return$p;});return $this->collection($parties);}
}
